const staticData = $getWorkflowStaticData('global');
staticData.LOW_COST_MODE = true;
staticData.MAX_RESULTS_PER_SEARCH = 20;
staticData.workflowStartedAt = new Date().toISOString();
staticData.searchesProcessed = 0;
staticData.leadsCaptured = 0;
staticData.leadsVerified = 0;
staticData.errorsEncountered = 0;
return $input.all();

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const dedupKeys = [];

for (const item of items) {
  const lead = item.json;
  let key = '';

  if (lead.website) {
    key = 'website:' + String(lead.website).toLowerCase().trim()
      .replace(/^https?:\/\//, '')
      .replace(/www\./, '')
      .replace(/\/+$/, '');
  } else if (lead.phone) {
    key = 'phone:' + String(lead.phone).replace(/[^\d+]/g, '');
  } else if (lead.business_name && lead.city && lead.state) {
    key = 'ncs:' + [
      String(lead.business_name).toLowerCase().trim(),
      String(lead.city).toLowerCase().trim(),
      String(lead.state).toLowerCase().trim()
    ].join('|');
  }

  if (key) dedupKeys.push(key);
}

staticData.verifiedDedupKeys = [...new Set(dedupKeys)];
staticData.verifiedLeadCount = dedupKeys.length;
return $input.all();

const items = $input.all();
const pending = [];

for (const item of items) {
  const status = String(item.json.status || '').trim();
  if (status === 'Pending' || status === '') {
    pending.push(item);
  }
}

if (pending.length === 0) {
  return [{ json: { _noPending: true, _message: 'All searches completed or failed' } }];
}

return pending;

const items = $input.all();

// Get the dedupe keys loaded from the Google Sheet.
const cacheOutput = $('Cache Dedup Keys').all();

const existingKeys = new Set();

for (const item of cacheOutput) {
  const data = item.json;

  // Support either a single key or an array of keys.
  if (Array.isArray(data.verifiedDedupKeys)) {
    for (const key of data.verifiedDedupKeys) {
      if (key) existingKeys.add(String(key).trim());
    }
  }

  if (data.dedupe_key) {
    existingKeys.add(String(data.dedupe_key).trim());
  }
}

const verified = [];
const seenThisRun = new Set();

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const lead = item.json;

  const key = String(lead.dedupe_key || '').trim();

  if (!key) continue;

  // Already exists in Verified Leads.
  if (existingKeys.has(key)) continue;

  // Prevent duplicates between providers in this same run.
  if (seenThisRun.has(key)) continue;

  seenThisRun.add(key);

  verified.push({
    json: {
      lead_id: lead.lead_id,
      business_name: lead.business_name,
      niche: lead.niche,
      city: lead.city,
      state: lead.state,
      country: lead.country,
      address: lead.address,
      phone: lead.phone,
      website: lead.website,
      rating: lead.rating,
      review_count: lead.review_count,
      google_maps_url: lead.google_maps_url,
      business_type: lead.business_type,
      source: lead.source,
      search_input_id: lead.search_input_id,
      dedupe_key: key,
      verified_at: new Date().toISOString(),
      manual_review_notes: ''
    },
    // n8n item linking: link this output to the input item it came from.
    // A Code node returning new, unequal-count items must set pairedItem,
    // otherwise $('...').item downstream loses the thread (Paired item data
    // ... is unavailable).
    pairedItem: { item: index }
  });
}

if (verified.length === 0) {
  const sentinel = {
    json: {
      _noNewVerified: true,
      _message: 'All leads already exist in Verified Leads'
    }
  };

  // Every input of one loop iteration traces to the same upstream item, so
  // index 0 keeps $('Set Status Running').item resolvable downstream.
  if (items.length > 0) {
    sentinel.pairedItem = { item: 0 };
  }

  return [sentinel];
}

return verified;

const staticData = $getWorkflowStaticData('global');
const response = $input.first().json;
const searchInput = $('Build OSM API Query').first().json;

const statusCode = response.statusCode || 0;
const body = response.body || response;
const error = body.error || {};
const errorMsg = error.message
  || error.status
  || 'HTTP error ' + statusCode
  || 'Unknown API error';

staticData.errorsEncountered = (staticData.errorsEncountered || 0) + 1;

return [{
  json: {
    input_id: searchInput.input_id || '',
    _errorMessage: 'Places API error: ' + errorMsg + ' (HTTP ' + statusCode + ')',
    _rawStatus: error.status || ('HTTP ' + statusCode)
  }
}];

const items = $input.all();

const HVAC_CATEGORY_ID = '63be6904847c3692a84b9b56';

const positivePatterns = [
  /\bhvac\b/i,
  /\bair\s*conditioning\b/i,
  /\bair\s*conditioner\b/i,
  /\bair\s*cond\b/i,
  /\bheating\s*(?:and|&)\s*air\b/i,
  /\bheating\s*(?:and|&)\s*cooling\b/i,
  /\bcooling\s*(?:and|&)\s*heating\b/i,
  /\bheating\s*(?:and|&)\s*(?:a\/?c|ac)\b/i,
  /\bair\s*(?:ac|a\/c)\s*(?:and|&)\s*(?:heating|heat|conditioning)\b/i,
  /\bheating\s*(?:and|&)\s*(?:air|cooling)\b/i,
  /\bair\s*(?:and|&)\s*heat\b/i,
  /\bair\s*repair\b/i,
  /\bair\s*(?:solutions?|services?|choice|control|masters?|flow|works?|pro|quality|specialists?|balance|systems?)\b/i,
  /\benvironmental\s*air\b/i,
  /\bclimate\s*control\b/i,
  /\bmechanical\b/i,
  /\baire\b/i,
];

const rejectPatterns = [
  /\bcredit\b/i,
  /\broofing\b/i,
  /\bplumbing\b/i,
  /\bflooring\b/i,
  /\bpainting\b/i,
  /\binsulation\b/i,
  /\bfoundation\b/i,
  /\bconcrete\b/i,
  /\bcarpet\b/i,
  /\bdryer\s+vents?\b/i,
  /\bducts?\s*cleaning\b/i,
  /\bpower\s+cleaning\b/i,
  /\bsupply\b/i,
  /\bwholesale\b/i,
  /\bhardware\b/i,
  /\brental\b/i,
  /\bconstruction\s+supply\b/i,
];

const reviewPatterns = [
  /\bpump\b/i,
  /\bengineering\b/i,
  /\bdesign\b/i,
  /\belectric\b/i,
  /\belectrical\b/i,
  /\bappliance\b/i,
  /\bmechanical\b/i,
  /\bfacility\b/i,
  /\bconstruction\b/i,
];

const suspiciousWebsitePatterns = [
  /(^|\.)trane\.com(\/|$)/i,
  /rental-services/i,
];

function clean(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return clean(value).toLowerCase();
}

function normalizePhone(value) {
  const digits = String(value == null ? '' : value).replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('1')) {
    return digits.slice(1);
  }
  return digits;
}

function normalizeState(value) {
  const state = normalize(value);

  const aliases = {
    tx: 'tx',
    texas: 'tx',
  };

  return aliases[state] || state;
}

function getAddress(location) {
  return clean(
    location.formatted_address ||
    [
      location.address,
      location.address_extended,
      location.locality,
      location.region,
      location.postcode,
    ]
      .filter(Boolean)
      .join(', ')
  );
}

function getCategoryNames(categories) {
  return (categories || [])
    .map(c => clean(c.name))
    .filter(Boolean);
}

function getCategoryIds(categories) {
  return (categories || [])
    .map(c => clean(c.id) || clean(c.fsq_category_id))
    .filter(Boolean);
}

function buildDedupeKey({
  phone,
  website,
  businessName,
  city,
  state,
}) {
  if (phone) {
    return `phone:${normalizePhone(phone)}`;
  }

  if (website) {
    return `website:${normalize(website)
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .replace(/\/$/, '')}`;
  }

  return `business:${normalize(businessName)}|${normalize(city)}|${normalizeState(state)}`;
}


/*
 * ============================================================
 * RESTORE SEARCH CONTEXT
 * ============================================================
 */

let searchContext = {};

try {
  const upstream = $('Build FSQ API Query').all();

  if (upstream.length > 0) {
    searchContext =
      upstream[upstream.length - 1].json || {};
  }
} catch (error) {
  searchContext = {};
}

const searchInputId = clean(
  searchContext.input_id ||
  searchContext.search_input_id ||
  ''
);

const niche = clean(
  searchContext.niche ||
  'HVAC'
);

const targetCity = clean(
  searchContext.city ||
  'Dallas'
);

const targetState = clean(
  searchContext.state ||
  'TX'
);

const country = clean(
  searchContext.country ||
  'USA'
);


/*
 * ============================================================
 * PROCESS FOURSQUARE RESPONSE
 * ============================================================
 */

const output = [];
const seen = new Set();

for (const item of items) {
  const response = item.json || {};
  const places = response.results || [];

  for (const place of places) {
    const location = place.location || {};
    const categories = place.categories || [];

    const businessName = clean(place.name);

    const city = clean(location.locality);

    const state = clean(location.region);

    const phone = normalizePhone(place.tel);

    const website = clean(place.website);

    const address = getAddress(location);

    if (!businessName) {
      continue;
    }


    /*
     * ========================================================
     * GEOGRAPHY
     * ========================================================
     *
     * Accept TX and Texas as equivalent.
     */

    if (
      city &&
      normalize(city) !== normalize(targetCity)
    ) {
      continue;
    }

    if (
      state &&
      normalizeState(state) !== normalizeState(targetState)
    ) {
      continue;
    }


    /*
     * Must have usable prospect data.
     */

    if (!phone && !website && !address) {
      continue;
    }


    /*
     * ========================================================
     * HVAC RELEVANCE
     * ========================================================
     */

    const categoryNames =
      getCategoryNames(categories);

    const categoryIds =
      getCategoryIds(categories);

    const hvacCategoryMatch =
      categoryIds.includes(HVAC_CATEGORY_ID);

    const hvacNameMatch =
      positivePatterns.some(pattern =>
        pattern.test(businessName)
      );


    /*
     * Must actually look like HVAC.
     */

    if (
      !hvacCategoryMatch &&
      !hvacNameMatch
    ) {
      continue;
    }


    /*
     * ========================================================
     * NON-HVAC REJECTION
     * ========================================================
     */

    const rejected =
      rejectPatterns.some(pattern =>
        pattern.test(businessName)
      ) ||
      rejectPatterns.some(pattern =>
        pattern.test(categoryNames.join(' '))
      );

    if (rejected) {
      continue;
    }


    /*
     * ========================================================
     * QUALIFICATION
     * ========================================================
     */

    const suspiciousWebsite =
      suspiciousWebsitePatterns.some(pattern =>
        pattern.test(website)
      );

    let qualification = 'QUALIFIED';
    let reason = 'hvac_category_and_name_match';

    if (suspiciousWebsite) {
      qualification = 'REVIEW';
      reason =
        'suspicious_or_parent_company_website';
    } else if (
      hvacCategoryMatch &&
      !hvacNameMatch
    ) {
      qualification = 'REVIEW';
      reason =
        'hvac_category_without_strong_name_match';
    } else if (
      reviewPatterns.some(pattern =>
        pattern.test(businessName)
      ) ||
      reviewPatterns.some(pattern =>
        pattern.test(categoryNames.join(' '))
      )
    ) {
      qualification = 'REVIEW';
      reason =
        'ambiguous_business_identity';
    }


    /*
     * ========================================================
     * DEDUPE
     * ========================================================
     */

    const dedupeKey = buildDedupeKey({
      phone,
      website,
      businessName,
      city: city || targetCity,
      state: state || targetState,
    });

    if (seen.has(dedupeKey)) {
      continue;
    }

    seen.add(dedupeKey);


    /*
     * ========================================================
     * LEAD ID
     * ========================================================
     */

    let leadId;

    if (phone) {
      leadId =
        `FSQ-PHONE-${phone.replace(/\D/g, '')}`;
    } else if (website) {
      leadId =
        `FSQ-WEB-${normalize(website)
          .replace(/^https?:\/\//, '')
          .replace(/^www\./, '')
          .replace(/[^a-z0-9]/g, '')}`;
    } else {
      leadId =
        `FSQ-${normalize(businessName)
          .replace(/[^a-z0-9]+/g, '-')
          .replace(/^-|-$/g, '')}`;
    }


    /*
     * ========================================================
     * RAW LEADS OUTPUT
     * ========================================================
     */

    output.push({
      json: {
        lead_id: leadId,

        business_name: businessName,

        niche,

        city: city || targetCity,

        state: state || targetState,

        country,

        address,

        phone,

        website,

        rating: 0,

        review_count: 0,

        google_maps_url: '',

        business_type:
          categoryNames.join(', ') ||
          'HVAC',

        source: 'FOURSQUARE',

        search_input_id: searchInputId,

        dedupe_key: dedupeKey,

        raw_captured_at:
          new Date().toISOString(),

        notes:
          `fsq_qualification=${qualification}; ` +
          `reason=${reason}; ` +
          `hvac_category_match=${hvacCategoryMatch}; ` +
          `hvac_name_match=${hvacNameMatch}; ` +
          `fsq_place_id=${clean(place.fsq_place_id)}`,
      },
    });
  }
}

if (output.length === 0) {
  return [{ json: { _noResults: true, _message: 'Foursquare returned zero results', _provider: 'foursquare' } }];
}

return output;

const staticData = $getWorkflowStaticData('global');
const input = $input.first();
const payload = input.json || {};

const error = payload.error || {};
const httpCode = error.httpCode ?? error.statusCode ?? payload.statusCode ?? 0;
const errorMsg = error.message || error.description || 'Unknown API error';
const statusText = httpCode ? ` (HTTP ${httpCode})` : '';

let searchInput = {};

try {
  searchInput = $('Build FSQ API Query').first().json || {};
} catch {
  searchInput = {};
}

const inputId = searchInput.input_id || '';

staticData.errorsEncountered = (staticData.errorsEncountered || 0) + 1;

return [{
  json: {
    input_id: inputId,
    search_input_id: inputId,
    _provider: 'foursquare',
    _status: 'error',
    _errorMessage: 'Foursquare API error: ' + errorMsg + statusText,
    _rawStatus: httpCode ? ('HTTP ' + httpCode) : 'ERROR',
    source: 'foursquare:error',
    notes: 'Foursquare API error: ' + errorMsg + statusText
  }
}];

const staticData = $getWorkflowStaticData('global');

const input = $input.first().json;

const targetCount = Number(input.target_count) || 1;

// Candidate pool should be larger than the requested final count
// so Process Results can filter poor-quality OSM objects.
const candidateMultiplier = 5;

const candidatePoolSize = Math.max(
  targetCount * candidateMultiplier,
  20
);

// Respect the global workflow safety ceiling.
const maxCandidates =
  Number(staticData.MAX_RESULTS_PER_SEARCH) || 100;

const effectiveCandidatePool = Math.min(
  candidatePoolSize,
  maxCandidates
);

const city = String(input.city || '').trim();
const niche = String(input.niche || '').trim().toLowerCase();

let nicheQuery = '';

if (niche === 'hvac') {
  nicheQuery = `
  nwr["craft"="hvac"](area.search);
  nwr["shop"="heating"](area.search);
  nwr["shop"="air_conditioning"](area.search);
  `;
} else if (niche === 'plumbing') {
  nicheQuery = `
  nwr["craft"="plumber"](area.search);
  nwr["shop"="plumbing"](area.search);
  `;
} else if (niche === 'roofing') {
  nicheQuery = `
  nwr["craft"="roofer"](area.search);
  nwr["shop"="roofing"](area.search);
  `;
} else if (niche === 'electrical') {
  nicheQuery = `
  nwr["craft"="electrician"](area.search);
  nwr["shop"="electrical"](area.search);
  `;
} else if (niche === 'pest') {
  nicheQuery = `
  nwr["craft"="pest_control"](area.search);
  `;
} else {
  nicheQuery = `
  nwr["name"](area.search);
  `;
}

const apiQuery = `
[out:json][timeout:60];

area["name"="${city}"]["boundary"="administrative"]->.search;

(
${nicheQuery}
);

out center tags ${effectiveCandidatePool};
`.trim();

return [{
  json: {
    ...input,

    _apiQuery: apiQuery,

    // Final number of leads we actually want.
    _maxResults: targetCount,

    // Number of OSM candidates we attempt to retrieve.
    _candidatePoolSize: effectiveCandidatePool,

    _provider: 'openstreetmap_overpass'
  }
}];

const input = $json;

return [{
  json: {
    ...input,

    fsq_query: input.niche || 'HVAC',
    fsq_near: `${input.city}, ${input.state}`,
    fsq_limit: Math.min(Number(input.target_count || 10) * 3, 50),

    // Foursquare HVAC contractor category
    fsq_category_id: '63be6904847c3692a84b9b56',

    discovery_source: 'FOURSQUARE'
  }
}];

const item = $input.first().json;

const response = item.body || item;
const elements = response.elements || [];

// Preserve search context from the existing upstream node.
const buildQueryOutput = $('Build OSM API Query').all();

const osmContext =
  buildQueryOutput.length > 0
    ? buildQueryOutput[0].json
    : {};

const searchInputId = String(
  osmContext.input_id || ''
).trim();

const targetNiche = String(
  osmContext.niche || 'HVAC'
).trim();

const targetCity = String(
  osmContext.city || 'Dallas'
).trim();

const targetState = String(
  osmContext.state || 'Texas'
).trim();

const targetCountry = String(
  osmContext.country || 'USA'
).trim();

// Reject obvious non-prospect / facility / equipment records.
const rejectPatterns = [
  /\bsystem\b/i,
  /\bchiller\b/i,
  /\bboiler\b/i,
  /\bhydronic\b/i,
  /\binfrastructure\b/i,
  /\bequipment\b/i,
  /\binstallation\b/i,
  /\bplant\b/i,
  /\bfacility\b/i,
  /\bpipeline\b/i,
  /\bworkshop\b/i,
  /\bmaintenance\s+workshop\b/i
];

function clean(value) {
  return String(value ?? '').trim();
}

function normalizePhone(value) {
  const digits = String(value == null ? '' : value).replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('1')) {
    return digits.slice(1);
  }
  return digits;
}

function normalizeWebsite(value) {
  const raw = clean(value);

  if (!raw) return '';

  if (/^https?:\/\//i.test(raw)) {
    return raw;
  }

  return `https://${raw}`;
}

function getName(tags) {
  return clean(
    tags.name ||
    tags.official_name ||
    tags.brand
  );
}

function getPhone(tags) {
  return normalizePhone(
    tags.phone ||
    tags['contact:phone'] ||
    tags['contact:mobile'] ||
    ''
  );
}

function getWebsite(tags) {
  return normalizeWebsite(
    tags.website ||
    tags['contact:website'] ||
    ''
  );
}

function getAddress(tags) {
  const houseNumber = clean(tags['addr:housenumber']);
  const street = clean(
    tags['addr:street'] ||
    tags['addr:place']
  );

  if (houseNumber && street) {
    return `${houseNumber} ${street}`;
  }

  return street;
}

function getLeadId(element) {
  const type = clean(element.type).toUpperCase();
  const id = clean(element.id);

  if (type && id) {
    return `OSM-${type}-${id}`;
  }

  const name = getName(element.tags || '');

  return `OSM-${name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '') || 'UNKNOWN'}`;
}

const output = [];
const seen = new Set();

for (const element of elements) {
  const tags = element.tags || {};

  const name = getName(tags);

  if (!name) {
    continue;
  }

  // Reject obvious non-prospect objects.
  if (rejectPatterns.some(pattern => pattern.test(name))) {
    continue;
  }

  const phone = getPhone(tags);
  const website = getWebsite(tags);
  const address = getAddress(tags);

  // Require at least one usable business identifier.
  if (!phone && !website && !address) {
    continue;
  }

  const city =
    clean(tags['addr:city']) ||
    clean(targetCity);

  const state =
    clean(tags['addr:state']) ||
    clean(targetState);

  const country =
    clean(tags['addr:country']) ||
    clean(targetCountry);

  // Dedupe within this OSM batch:
  // phone -> website -> business/city/state
  const dedupeKey =
    phone
      ? `phone:${phone}`
      : website
        ? `website:${website.toLowerCase()}`
        : `business:${name.toLowerCase()}|${city.toLowerCase()}|${state.toLowerCase()}`;

  if (seen.has(dedupeKey)) {
    continue;
  }

  seen.add(dedupeKey);

  output.push({
    json: {
      lead_id: getLeadId(element),
      business_name: name,
      niche: targetNiche,
      city,
      state,
      country,
      address,
      phone,
      website,
      rating: 0,
      review_count: 0,
      google_maps_url: '',
      business_type:
        clean(tags.craft) ||
        clean(tags.shop) ||
        clean(tags.office) ||
        targetNiche.toLowerCase(),
      source: 'OSM',
      search_input_id: searchInputId,
      dedupe_key: dedupeKey,
      raw_captured_at: new Date().toISOString(),
      notes: JSON.stringify({
        osm_type: element.type,
        osm_id: element.id,
        coordinates:
          element.lat !== undefined && element.lon !== undefined
            ? {
                lat: element.lat,
                lon: element.lon
              }
            : element.center || {}
      })
    }
  });
}

if (output.length === 0) {
  return [{ json: { _noResults: true, _message: 'OpenStreetMap returned zero results', _provider: 'openstreetmap' } }];
}

return output;

const staticData = $getWorkflowStaticData('global');
const input = $input.first();
const payload = input.json || {};

const error = payload.error || {};
const httpCode = error.httpCode ?? error.statusCode ?? payload.statusCode ?? 0;
const errorMsg = error.message || error.description || 'Unknown API error';
const statusText = httpCode ? ` (HTTP ${httpCode})` : '';

let searchInput = {};

try {
  searchInput = $('Build OSM API Query').first().json || {};
} catch {
  searchInput = {};
}

const inputId = searchInput.input_id || '';

staticData.errorsEncountered = (staticData.errorsEncountered || 0) + 1;

return [{
  json: {
    input_id: inputId,
    search_input_id: inputId,
    _provider: 'openstreetmap',
    _status: 'error',
    _errorMessage: 'OpenStreetMap API error: ' + errorMsg + statusText,
    _rawStatus: httpCode ? ('HTTP ' + httpCode) : 'ERROR',
    source: 'openstreetmap:error',
    notes: 'OpenStreetMap API error: ' + errorMsg + statusText
  }
}];

const items = $input.all();

return items.filter((item) => {
  const json = item.json || {};

  // Provider succeeded but returned zero results: suppress silently.
  if (json._noResults === true) {
    return false;
  }

  // Provider failure signals must propagate (never silently discarded).
  if (
    json._errorMessage !== undefined ||
    json._status === 'error' ||
    json.status === 'error'
  ) {
    return true;
  }

  // Real lead rows propagate.
  if (json.lead_id || json.business_name || json.dedupe_key) {
    return true;
  }

  // Anything else with payload content is kept; truly empty objects never.
  return Object.keys(json).length > 0;
});

return $input.all().map(item => {
  const lead = item.json;

  return {
    json: {
      lead_id: lead.lead_id,
      business_name: lead.business_name,
      niche: lead.niche,
      city: lead.city,
      state: lead.state,
      country: lead.country,
      address: lead.address,
      phone: lead.phone,
      website: lead.website,
      rating: lead.rating,
      review_count: lead.review_count,
      google_maps_url: lead.google_maps_url,
      business_type: lead.business_type,
      source: lead.source,
      search_input_id: lead.search_input_id,
      dedupe_key: lead.dedupe_key,

      verified_at: lead.verified_at,
      notes: lead.notes || '',
      manual_review_notes: lead.manual_review_notes || ''
    }
  };
});

const input = $json;

return [{
  json: {
    ...input,

    gpl_query: input.search_query || `${input.niche} in ${input.city}, ${input.state}`,
    gpl_max_results: Math.min(Number(input.target_count || 1) * 3, 20),

    discovery_source: 'GOOGLE_PLACES'
  }
}];

const staticData = $getWorkflowStaticData('global');
const response = $input.first().json;
const searchInput = $('Build GPL API Query').first().json;

const statusCode = response.statusCode || 0;
const body = response.body || response;
const error = body.error || {};

if (statusCode !== 200 || error.code) {
  const errorMsg = error.message || error.status || 'HTTP error ' + statusCode || 'Unknown API error';
  staticData.errorsEncountered = (staticData.errorsEncountered || 0) + 1;

  return [{
    json: {
      input_id: searchInput.input_id || '',
      _errorMessage: 'Google Places API error: ' + errorMsg + ' (HTTP ' + statusCode + ')',
      _rawStatus: error.status || ('HTTP ' + statusCode),
      _provider: 'google_places'
    }
  }];
}

const places = body.places || [];
const capturedAt = new Date().toISOString();

const maxResults = Math.min(
  Number(searchInput.target_count || 1) * 3,
  20,
  Number(staticData.MAX_RESULTS_PER_SEARCH) || 20
);

const rejectPatterns = [
  /\bcredit\b/i,
  /\broofing\b/i,
  /\bplumbing\b/i,
  /\bflooring\b/i,
  /\bpainting\b/i,
  /\binsulation\b/i,
  /\bfoundation\b/i,
  /\bconcrete\b/i,
  /\bcarpet\b/i,
  /\bdryer\s+vents?\b/i,
  /\bducts?\s*cleaning\b/i,
  /\bpower\s+cleaning\b/i,
  /\bsupply\b/i,
  /\bwholesale\b/i,
  /\bhardware\b/i,
  /\brental\b/i,
  /\bconstruction\s+supply\b/i,
];

const STATE_ALIASES = {
  'alabama': 'al', 'alaska': 'ak', 'arizona': 'az', 'arkansas': 'ar',
  'california': 'ca', 'colorado': 'co', 'connecticut': 'ct', 'delaware': 'de',
  'district of columbia': 'dc', 'florida': 'fl', 'georgia': 'ga',
  'hawaii': 'hi', 'idaho': 'id', 'illinois': 'il', 'indiana': 'in',
  'iowa': 'ia', 'kansas': 'ks', 'kentucky': 'ky', 'louisiana': 'la',
  'maine': 'me', 'maryland': 'md', 'massachusetts': 'ma', 'michigan': 'mi',
  'minnesota': 'mn', 'mississippi': 'ms', 'missouri': 'mo', 'montana': 'mt',
  'nebraska': 'ne', 'nevada': 'nv', 'new hampshire': 'nh', 'new jersey': 'nj',
  'new mexico': 'nm', 'new york': 'ny', 'north carolina': 'nc',
  'north dakota': 'nd', 'ohio': 'oh', 'oklahoma': 'ok', 'oregon': 'or',
  'pennsylvania': 'pa', 'rhode island': 'ri', 'south carolina': 'sc',
  'south dakota': 'sd', 'tennessee': 'tn', 'texas': 'tx', 'utah': 'ut',
  'vermont': 'vt', 'virginia': 'va', 'washington': 'wa',
  'west virginia': 'wv', 'wisconsin': 'wi', 'wyoming': 'wy',
};

const STATE_CODE_REGEX = /^(al|ak|az|ar|ca|co|ct|de|dc|fl|ga|hi|id|il|in|ia|ks|ky|la|me|md|ma|mi|mn|ms|mo|mt|ne|nv|nh|nj|nm|ny|nc|nd|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|vt|va|wa|wv|wi|wy)$/;

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeState(value) {
  const state = clean(value).toLowerCase();
  if (STATE_CODE_REGEX.test(state)) return state;
  return STATE_ALIASES[state] || '';
}

function extractGeo(formattedAddress) {
  const address = clean(formattedAddress);
  if (!address) return null;

  const segments = address.split(',').map((s) => clean(s)).filter(Boolean);
  const STATE_SEGMENT = /^([A-Za-z][\w.' ]*?)\s+(\d{5})(?:[-\s]\d{4})?$/;

  for (let idx = 0; idx < segments.length; idx++) {
    const match = segments[idx].match(STATE_SEGMENT);
    if (!match) continue;

    const tokens = match[1].trim().split(/\s+/);
    const state = normalizeState(tokens[tokens.length - 1]);
    if (!state) continue;

    const cityInSegment = tokens.slice(0, -1).join(' ').toLowerCase();
    const city = cityInSegment || (idx > 0 ? segments[idx - 1].toLowerCase() : '');
    return { city, state };
  }

  return null;
}

function normalizeWebsite(value) {
  const raw = clean(value);
  if (!raw) return '';
  return raw
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/+$/, '');
}

function normalizePhone(value) {
  const raw = clean(value);
  if (!raw) return '';
  return raw.replace(/[^\d+]/g, '');
}

function buildDedupeKey(lead) {
  if (lead.website) {
    return 'website:' + normalizeWebsite(lead.website).toLowerCase();
  }
  if (lead.phone) {
    return 'phone:' + normalizePhone(lead.phone);
  }
  if (lead.business_name && lead.city && lead.state) {
    return 'ncs:' + [
      clean(lead.business_name).toLowerCase(),
      clean(lead.city).toLowerCase(),
      clean(lead.state).toLowerCase()
    ].join('|');
  }
  return '';
}

function generateLeadId(placeId, index) {
  const str = String(placeId || '') + ':' + index;
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  return 'GP-' + hex;
}

const targetCity = clean(searchInput.city).toLowerCase();
const targetState = normalizeState(clean(searchInput.state || ''));
const leads = [];
let relevanceRejected = 0;
let geoRejected = 0;
let noContact = 0;
for (let i = 0; i < Math.min(places.length, maxResults); i++) {
  const place = places[i];
  const displayName = place?.displayName?.text ?? '';
  if (!displayName) continue;

  const types = place?.types || [];
  if (
    rejectPatterns.some((pattern) => pattern.test(displayName)) ||
    rejectPatterns.some((pattern) => pattern.test(types.join(' ')))
  ) {
    relevanceRejected++;
    continue;
  }

  const geo = extractGeo(place?.formattedAddress);
  if (!geo || !geo.state) {
    geoRejected++;
    continue;
  }
  let geoOk = false;
  if (geo.city) {
    if (targetCity && geo.city === targetCity) geoOk = true;
    else if (targetCity) {
      geoRejected++;
      continue;
    }
  }
  if (geo.state) {
    if (targetState && geo.state === targetState) geoOk = true;
    else if (targetState) {
      geoRejected++;
      continue;
    }
  }
  if (!geoOk) {
    geoRejected++;
    continue;
  }

  const formattedAddress = clean(place?.formattedAddress);
  const phone = normalizePhone(place?.internationalPhoneNumber);
  const website = normalizeWebsite(place?.websiteUri);
  const rating = place?.rating !== undefined && place?.rating !== null ? String(place.rating) : '';
  const reviewCount = place?.userRatingCount !== undefined && place?.userRatingCount !== null ? String(place.userRatingCount) : '';
  const googleMapsUrl = clean(place?.googleMapsUri);
  const businessType = types[0] || 'establishment';
  const placeId = place?.id || '';

  const lead = {
    lead_id: generateLeadId(placeId, i),
    business_name: displayName,
    niche: clean(searchInput.niche),
    city: clean(searchInput.city),
    state: clean(searchInput.state),
    country: clean(searchInput.country),
    address: formattedAddress,
    phone,
    website,
    rating,
    review_count: reviewCount,
    google_maps_url: googleMapsUrl,
    business_type: businessType,
    source: 'google_places',
    search_input_id: clean(searchInput.input_id),
    dedupe_key: buildDedupeKey({ website, phone, business_name: displayName, city: clean(searchInput.city), state: clean(searchInput.state) }),
    raw_captured_at: capturedAt,
    notes: 'Google Places: ' + (searchInput.search_query || (clean(searchInput.niche) + ' in ' + clean(searchInput.city) + ', ' + clean(searchInput.state))) + '; gp_place_id:' + placeId
  };

  if (!lead.phone && !lead.website) {
    lead.dedupe_key = '';
    lead.notes += '; no_contact=true';
    noContact++;
  }

  leads.push({ json: lead });
}

staticData.gplRelevanceRejected = (staticData.gplRelevanceRejected || 0) + relevanceRejected;
staticData.gplGeoRejected = (staticData.gplGeoRejected || 0) + geoRejected;
staticData.gplNoContact = (staticData.gplNoContact || 0) + noContact;

if (leads.length === 0 && (relevanceRejected > 0 || geoRejected > 0)) {
  return [{ json: { _noResults: true, _message: 'Google Places returned zero qualified results', _provider: 'google_places', _gplRelevanceRejected: relevanceRejected, _gplGeoRejected: geoRejected } }];
}

if (leads.length === 0) {
  return [{ json: { _noResults: true, _message: 'Google Places returned zero results', _provider: 'google_places' } }];
}

return leads;

